1250	//
1251	// This is called at stop time to finalize all checkpoints from the current turn
1252	// with the complete session transcript (from prompt to stop event).
1253	//
1254	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1255	func (s *GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
1256		if opts.CheckpointID.IsEmpty() {
1257			return errors.New("invalid update options: checkpoint ID is required")
1258		}
1259	
1260		// Ensure sessions branch exists
1261		if err := s.ensureSessionsBranch(ctx); err != nil {
1262			return fmt.Errorf("failed to ensure sessions branch: %w", err)
1263		}
1264	
1265		// Get branch ref and root tree hash (O(1), no flatten)
1266		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1267		if err != nil {
1268			return err
1269		}
1270	
1271		// Flatten only the checkpoint subtree
1272		basePath := opts.CheckpointID.Path() + "/"
1273		checkpointPath := opts.CheckpointID.Path()
1274		entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1275		if err != nil {
1276			return err
1277		}
1278	
1279		// Read root CheckpointSummary to find the session slot
1280		rootMetadataPath := basePath + paths.MetadataFileName
1281		entry, exists := entries[rootMetadataPath]
1282		if !exists {
1283			return ErrCheckpointNotFound
1284		}
1285	
1286		checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1287		if err != nil {
1288			return fmt.Errorf("failed to read checkpoint summary: %w", err)
1289		}
1290		if len(checkpointSummary.Sessions) == 0 {
1291			return ErrCheckpointNotFound
1292		}
1293	
1294		// Find session index matching opts.SessionID
1295		sessionIndex := -1
1296		for i := range len(checkpointSummary.Sessions) {
1297			metaPath := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
1298			if metaEntry, metaExists := entries[metaPath]; metaExists {
1299				meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
1300				if metaErr == nil && meta.SessionID == opts.SessionID {
1301					sessionIndex = i
1302					break
1303				}
1304			}
1305		}
1306		if sessionIndex == -1 {
1307			// Fall back to latest session; log so mismatches are diagnosable.
1308			sessionIndex = len(checkpointSummary.Sessions) - 1
1309			logging.Debug(ctx, "UpdateCommitted: session ID not found, falling back to latest",
1310				slog.String("session_id", opts.SessionID),
1311				slog.String("checkpoint_id", string(opts.CheckpointID)),
1312				slog.Int("fallback_index", sessionIndex),
1313			)
1314		}
1315	
1316		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1317	
1318		// Replace transcript (full replace, not append).
1319		// Transcript is pre-redacted by the caller (enforced by RedactedBytes type).
1320		if opts.Transcript.Len() > 0 {
1321			if err := s.replaceTranscript(ctx, opts.Transcript, opts.Agent, sessionPath, entries); err != nil {
1322				return fmt.Errorf("failed to replace transcript: %w", err)
1323			}
1324		}
1325	
1326		// Replace prompts (apply redaction as safety net)
1327		if len(opts.Prompts) > 0 {
1328			promptContent := redact.String(JoinPrompts(opts.Prompts))
1329			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
1330			if err != nil {
1331				return fmt.Errorf("failed to create prompt blob: %w", err)
1332			}
1333			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
1334				Name: sessionPath + paths.PromptFileName,
1335				Mode: filemode.Regular,
1336				Hash: blobHash,
1337			}
